<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableTypeVO;

trait TemplateVariableTypeAccessor {
  private TemplateVariableTypeVO $_type;
  public function getType(): string
  {
    return $this->_type->value();
  }
  public function type(): TemplateVariableTypeVO
  {
    return $this->_type;
  }
  public function isTypeChanged(?self $original = null): bool
  {
  return !$this->_type->equals( $original?->_type );  }
  public function withType(TemplateVariableTypeVO|string $type): self
  {
    $copy = clone $this;
    $copy->_type = TemplateVariableTypeVO::from( $type );
    return $copy;
  }
}